     9	
    10	public class StandardRatePlan implements RatePlan {
    11	    @Override
    12	    public void validate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    13	    }
    14	
    15	    @Override
    16	    public PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    17	        BigDecimal subtotal = calculateSubtotal(room, checkIn, checkOut);
    18	        BigDecimal discount = MoneyUtils.round(BigDecimal.ZERO);
    19	        BigDecimal total = subtotal;
    20	
    21	        return new PricingResult(subtotal, discount, total);
    22	    }
    23	
    24	    @Override
    25	    public BigDecimal calculateRefund(BigDecimal amountPaid) {
    26	        return amountPaid;
    27	    }
    28	
    29	    protected BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    30	        BigDecimal subtotal = BigDecimal.ZERO;
    31	        LocalDate current = checkIn;
    32	
    33	        while (current.isBefore(checkOut)) {
    34	            BigDecimal nightlyRate = room.getNightlyRate();
    35	
    36	            if (DateUtils.isHighSeason(current)) {
    37	                nightlyRate = MoneyUtils.round(nightlyRate.multiply(new BigDecimal("1.20")));
    38	            } else {
    39	                nightlyRate = MoneyUtils.round(nightlyRate);
    40	            }
    41	
    42	            subtotal = subtotal.add(nightlyRate);
    43	            current = current.plusDays(1);
    44	        }
    45	
    46	        return MoneyUtils.round(subtotal);
    47	    }
    48	}
