    10	import java.time.temporal.ChronoUnit;
    11	import java.util.Map;
    12	
    13	public class WeekendPackageRatePlan implements RatePlan {
    14	    private static final Map<RoomType, BigDecimal> PACKAGE_PRICES = Map.of(
    15	        RoomType.STANDARD, new BigDecimal("520.00"),
    16	        RoomType.DELUXE, new BigDecimal("820.00"),
    17	        RoomType.SUITE, new BigDecimal("1200.00")
    18	    );
    19	
    20	    @Override
    21	    public void validate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    22	        long nights = ChronoUnit.DAYS.between(checkIn, checkOut);
    23	
    24	        if (nights != 2) {
    25	            throw new IllegalArgumentException("Weekend package requires exactly 2 nights");
    26	        }
    27	
    28	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
    29	            throw new IllegalArgumentException("Weekend package must start on Friday");
    30	        }
    31	
    32	        if (checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
    33	            throw new IllegalArgumentException("Weekend package must end on Sunday");
    34	        }
    35	    }
    36	
    37	    @Override
    38	    public PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    39	        BigDecimal packagePrice = PACKAGE_PRICES.get(room.getType());
    40	        return new PricingResult(packagePrice, MoneyUtils.round(BigDecimal.ZERO), packagePrice);
    41	    }
    42	
    43	    @Override
    44	    public BigDecimal calculateRefund(BigDecimal amountPaid) {
    45	        return MoneyUtils.round(amountPaid.divide(new BigDecimal("2")));
    46	    }
    47	}
