    15	import java.util.concurrent.atomic.AtomicLong;
    16	
    17	public class ReservationService {
    18	    private final Map<Long, Reservation> reservations = new HashMap<>();
    19	    private final AtomicLong nextId = new AtomicLong(1);
    20	    private final RoomService roomService;
    21	    private final MessageService messageService;
    22	
    23	    public ReservationService(RoomService roomService, MessageService messageService) {
    24	        this.roomService = roomService;
    25	        this.messageService = messageService;
    26	    }
    27	
    28	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    29	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    30	                                        int guests, RatePlanType ratePlanType, String companyCode) {
    31	        Room room = roomService.getRoomByNumber(roomNumber)
    32	                .orElseThrow(() -> new RoomNotFoundException());
    33	
    34	        if (guests < 1) {
    35	            throw new InvalidRequestException("Number of guests must be at least 1");
    36	        }
    37	
    38	        if (guests > room.getCapacity()) {
    39	            throw new CapacityExceededException();
    40	        }
    41	
    42	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    43	            throw new InvalidRequestException("Check-out date must be after check-in date");
    44	        }
    45	
    46	        RatePlan ratePlan = RatePlanFactory.getRatePlan(ratePlanType);
    47	
    48	        try {
    49	            ratePlan.validate(room, checkIn, checkOut, companyCode);
    50	        } catch (IllegalArgumentException e) {
    51	            throw new InvalidRequestException(e.getMessage());
    52	        }
    53	
    54	        if (isRoomUnavailable(roomNumber, checkIn, checkOut, null)) {
    55	            throw new RoomUnavailableException();
    56	        }
    57	
    58	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    59	        PricingResult pricing = ratePlan.calculatePrice(room, checkIn, checkOut, companyCode);
    60	
    61	        Reservation reservation = new Reservation(
    62	            nextId.getAndIncrement(),
    63	            roomNumber,
    64	            guestName,
    65	            guestEmail,
    66	            guestCpf,
    67	            checkIn,
    68	            checkOut,
    69	            guests,
    70	            ratePlanType,
    71	            companyCode,
    72	            nights,
    73	            pricing.getSubtotal(),
    74	            pricing.getDiscount(),
    75	            pricing.getTotal()
    76	        );
    77	
    78	        reservations.put(reservation.getId(), reservation);
    79	        return reservation;
    80	    }
    81	
    82	    public Reservation getReservation(long id) {
    83	        return Optional.ofNullable(reservations.get(id))
    84	                .orElseThrow(() -> new ReservationNotFoundException());
    85	    }
    86	
    87	    public Reservation confirmReservation(long id) {
    88	        Reservation reservation = getReservation(id);
    89	
    90	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    91	            throw new OperationNotAllowedException();
    92	        }
    93	
    94	        reservation.setStatus(ReservationStatus.CONFIRMED);
    95	        reservation.setAmountPaid(reservation.getTotal());
    96	
    97	        sendConfirmationEmail(reservation);
    98	
    99	        return reservation;
   100	    }
   101	
   102	    public Reservation checkIn(long id) {
   103	        Reservation reservation = getReservation(id);
   104	
   105	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   106	            throw new OperationNotAllowedException();
   107	        }
   108	
   109	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   110	        return reservation;
   111	    }
   112	
   113	    public Reservation checkOut(long id) {
   114	        Reservation reservation = getReservation(id);
   115	
   116	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   117	            throw new OperationNotAllowedException();
   118	        }
   119	
   120	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   121	        return reservation;
   122	    }
   123	
   124	    public Reservation cancelReservation(long id) {
   125	        Reservation reservation = getReservation(id);
   126	
   127	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   128	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   129	            throw new OperationNotAllowedException();
   130	        }
   131	
   132	        RatePlan ratePlan = RatePlanFactory.getRatePlan(reservation.getRatePlan());
   133	        BigDecimal refund = ratePlan.calculateRefund(reservation.getAmountPaid());
   134	
   135	        reservation.setStatus(ReservationStatus.CANCELLED);
   136	        reservation.setRefund(refund);
   137	
   138	        return reservation;
   139	    }
   140	
   141	    public String generateDocument(long id) {
   142	        Reservation reservation = getReservation(id);
   143	
   144	        if (reservation.getStatus() == ReservationStatus.PENDING ||
   145	            reservation.getStatus() == ReservationStatus.CANCELLED) {
   146	            throw new OperationNotAllowedException();
   147	        }
   148	
   149	        return buildDocument(reservation);
   150	    }
   151	
   152	    public List<Reservation> getReservationsForOccupancyReport(LocalDate date) {
   153	        return reservations.values().stream()
   154	                .filter(r -> r.getStatus() != ReservationStatus.PENDING &&
   155	                           r.getStatus() != ReservationStatus.CANCELLED)
   156	                .filter(r -> !r.getCheckIn().isAfter(date) && r.getCheckOut().isAfter(date))
   157	                .sorted(Comparator.comparingInt(Reservation::getRoomNumber))
   158	                .toList();
   159	    }
   160	
   161	    public List<Reservation> getReservationsForRevenueReport(int year, int month) {
   162	        return reservations.values().stream()
   163	                .filter(r -> r.getCheckIn().getYear() == year &&
   164	                           r.getCheckIn().getMonthValue() == month)
   165	                .filter(r -> r.getAmountPaid().compareTo(BigDecimal.ZERO) > 0 ||
   166	                           (r.getRefund() != null && r.getRefund().compareTo(BigDecimal.ZERO) > 0))
   167	                .sorted(Comparator.comparing(Reservation::getCheckIn)
   168	                        .thenComparingLong(Reservation::getId))
   169	                .toList();
   170	    }
   171	
   172	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeReservationId) {
   173	        return reservations.values().stream()
   174	                .filter(r -> excludeReservationId == null || r.getId() != excludeReservationId)
   175	                .filter(r -> r.getRoomNumber() == roomNumber)
   176	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   177	                .anyMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
   178	    }
   179	
   180	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
   181	        return start1.isBefore(end2) && start2.isBefore(end1);
   182	    }
   183	
   184	    private void sendConfirmationEmail(Reservation reservation) {
   185	        String document = buildDocument(reservation);
   186	        String subject = "Reserva confirmada - Pousada Maré Alta";
   187	        String body = String.format(
   188	            "Olá, %s!\n\n" +
   189	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   190	            "%s\n\n" +
   191	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   192	            "Até breve!",
   193	            reservation.getGuestName(),
   194	            document
   195	        );
   196	
   197	        messageService.sendEmail(reservation.getGuestEmail(), subject, body);
   198	    }
   199	
   200	    private String buildDocument(Reservation reservation) {
   201	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber()).orElseThrow();
   202	
   203	        StringBuilder doc = new StringBuilder();
   204	        doc.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
   205	        doc.append(String.format("Hóspede: %s (CPF %s)\n",
   206	                reservation.getGuestName(),
   207	                CpfFormatter.format(reservation.getGuestCpf())));
   208	        doc.append(String.format("Quarto: %d (%s)\n",
   209	                reservation.getRoomNumber(),
   210	                room.getType()));
   211	        doc.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
   212	                DateUtils.formatForDisplay(reservation.getCheckIn()),
   213	                DateUtils.formatForDisplay(reservation.getCheckOut()),
   214	                reservation.getNights(),
   215	                reservation.getNights() == 1 ? "diária" : "diárias"));
   216	        doc.append(String.format("Diárias: %s\n",
   217	                MoneyUtils.formatMoney(reservation.getSubtotal())));
   218	
   219	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
   220	            doc.append(String.format("Desconto: %s\n",
   221	                    MoneyUtils.formatMoney(reservation.getDiscount())));
   222	        }
   223	
   224	        doc.append(String.format("Total: %s",
   225	                MoneyUtils.formatMoney(reservation.getTotal())));
   226	
   227	        return doc.toString();
   228	    }
