   233	        public InvalidRequestException(String message) {
   234	            super(message);
   235	        }
   236	    }
   237	    public static class CapacityExceededException extends RuntimeException {}
   238	    public static class RoomUnavailableException extends RuntimeException {}
   239	    public static class OperationNotAllowedException extends RuntimeException {}
