   124	    public Reservation cancelReservation(long id) {
   125	        Reservation reservation = getReservation(id);
   126	
   127	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   128	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   129	            throw new OperationNotAllowedException();
   130	        }
   131	
   132	        RatePlan ratePlan = RatePlanFactory.getRatePlan(reservation.getRatePlan());
   133	        BigDecimal refund = ratePlan.calculateRefund(reservation.getAmountPaid());
   134	
   135	        reservation.setStatus(ReservationStatus.CANCELLED);
   136	        reservation.setRefund(refund);
   137	
   138	        return reservation;
