    22	    public String generateOccupancyReport(LocalDate date) {
    23	        List<Reservation> reservations = reservationService.getReservationsForOccupancyReport(date);
    24	
    25	        StringBuilder csv = new StringBuilder();
    26	        csv.append("room,type,reservation,check_in,check_out\n");
    27	
