    46	                month.getYear(), month.getMonthValue());
    47	
    48	        StringBuilder csv = new StringBuilder();
    49	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    50	
    51	        BigDecimal total = BigDecimal.ZERO;
    52	
    53	        for (Reservation r : reservations) {
    54	            BigDecimal amount = r.getAmountPaid();
    55	            if (r.getRefund() != null) {
    56	                amount = amount.subtract(r.getRefund());
    57	            }
    58	
    59	            total = total.add(amount);
    60	
    61	            csv.append(String.format("%d,%d,%s,%s,%s,%.2f\n",
    62	                    r.getId(),
    63	                    r.getRoomNumber(),
    64	                    DateUtils.formatForApi(r.getCheckIn()),
    65	                    DateUtils.formatForApi(r.getCheckOut()),
    66	                    r.getStatus(),
    67	                    amount));
    68	        }
    69	
    70	        csv.append(String.format("total,,,,,%.2f", total));
    71	
    72	        return csv.toString();
    73	    }
